\begin{lemma}[A line contains exactly two unit vectors]
\label{lem:two-unit-vectors-of-a-line}




If unit vectors $u,u'$ in an inner product space span the same line, then
$u'=u$ or $u'=-u$.
\end{lemma}

\begin{proof}

\sketch Write $u'=cu$. Unit length gives $c^2=1$.
\end{proof}

